{
  "question_bank": {
    "description": "ZED Chatbot Question Bank — 50 questions categorised by topic. Use these to test the chatbot before demo.",
    "categories": {
      "basics": {
        "label": "What is ZED",
        "questions": [
          "What is ZED certification?",
          "What does Zero Defect Zero Effect mean?",
          "Who runs the ZED scheme?",
          "Is ZED certification mandatory for MSMEs?",
          "What is the goal of the ZED scheme?",
          "Where can I apply for ZED?",
          "What is the difference between ZED and ISO certification?"
        ]
      },
      "eligibility": {
        "label": "Eligibility",
        "questions": [
          "Who is eligible for ZED certification?",
          "Do I need UDYAM registration for ZED?",
          "Can a service sector enterprise apply for ZED?",
          "My turnover is 50 lakhs — am I a micro or small enterprise?",
          "Can a startup apply for ZED?",
          "I am not registered on UDYAM yet. What should I do first?"
        ]
      },
      "levels": {
        "label": "Bronze / Silver / Gold",
        "questions": [
          "What is the difference between Bronze, Silver, and Gold?",
          "Which level should I start with?",
          "Can I apply directly for Gold without Bronze?",
          "How long does Bronze certification take?",
          "Is there a site visit for Bronze certification?",
          "What happens after I get Bronze — how do I move to Silver?",
          "How long is the ZED certificate valid?"
