      },
      "documents": {
        "label": "Documents Needed",
        "questions": [
          "What documents do I need for Bronze certification?",
          "Is a quality policy document required for Bronze?",
          "Can I upload a draft quality policy or does it need to be final?",
          "How many photos of my factory do I need to upload?",
          "Do I need to upload GST certificate if I am not registered for GST?",
          "What is an organisational chart and how do I make one?",
          "Where do I upload documents — on the ZED portal?"
        ]
      },
      "subsidy": {
        "label": "Subsidy and Cost",
        "questions": [
          "How much subsidy can I get for ZED certification?",
          "I am a micro enterprise — how much subsidy will I receive?",
          "My enterprise is women-owned — do I get extra subsidy?",
          "I am from Assam — do I get any additional benefit?",
