        "questions": [
          "What are the 10 ZED parameters?",
          "Which parameter has the highest weightage?",
          "What is 5S — can you explain it simply?",
          "Do I need a full QMS system for Bronze?",
          "What does energy conservation mean in ZED context?",
          "I already have ISO 9001 — does that help in ZED?",
          "Which ISO certificates waive ZED parameters?",
          "I have FSSAI certificate — which ZED parameters are waived?"
        ]
      },
      "sectors": {
        "label": "Sector-Specific",
        "questions": [
          "I manufacture textiles — which guidance document should I read?",
          "I am in the food processing sector — is there a specific ZED guide?",
          "My NIC code is 25 — which guidance document applies to me?",
          "Where can I download the sector guidance documents?",
          "I am in the pharma sector — what specific parameters apply to me?"
