      },
      "benefits": {
        "label": "Benefits",
        "questions": [
          "What are the benefits of ZED certification?",
          "Will ZED certification help me get government tenders?",
          "Does ZED certification help in getting bank loans?",
          "What is the handholding support mentioned in ZED?"
